# ⚠ DO NOT REMOVE — scope: erp/ad_ctxhelp_rows.js, legacy's Context Help tables (AD_CtxHelp, AD_CtxHelpMsg, AD_CtxHelpMsg_Trl, AD_CtxHelpSuggestion) for the twin
# (bim-compiler prompts/VOCAB_MESSAGE_CATALOG.md §19.16 C1, W-CTXHELP-OVERLAY). AD_Task / AD_Task_Access and every AD_CtxHelp_ID link column already come with the seed +
# the hashed patch's G-DICT block, so they are not repeated here. EXTRACT ONLY from the reference Postgres `idempiere` (read-only). Shipped as a BOOT OVERLAY (erp/ad_ctxhelp_overlay.js), NOT in the
# hashed patches/ad_seed.db.sql, so the Team BASE hash does not move (build_docvalue_overlay.py precedent). Read the stderr § line after a run.
# Usage: python3 erp/patches/build_ctxhelp_overlay.py > erp/ad_ctxhelp_rows.js
import psycopg2, sys, datetime, decimal, json
cn = psycopg2.connect(host='localhost', user='adempiere', password='adempiere', dbname='idempiere'); cur = cn.cursor(); cur.execute('set search_path=adempiere')
TABLES = ['ad_ctxhelp', 'ad_ctxhelpmsg', 'ad_ctxhelpmsg_trl', 'ad_ctxhelpsuggestion']
def lit(v):
    if v is None: return 'NULL'
    if isinstance(v, bool): return "'Y'" if v else "'N'"
    if isinstance(v, (int, float, decimal.Decimal)): return str(v)
    if isinstance(v, datetime.datetime): return "'" + v.strftime('%Y-%m-%d %H:%M:%S') + "'"
    if isinstance(v, datetime.date): return "'" + v.strftime('%Y-%m-%d') + " 00:00:00'"
    return "'" + str(v).replace("'", "''") + "'"
def cols(t):
    cur.execute("select column_name, data_type from information_schema.columns where table_schema='adempiere' and table_name=%s order by ordinal_position", (t,)); return cur.fetchall()
def pk(t):
    cur.execute("select a.attname from pg_index i join pg_attribute a on a.attrelid=i.indrelid and a.attnum=any(i.indkey) where i.indrelid=('adempiere.'||%s)::regclass and i.indisprimary order by array_position(i.indkey, a.attnum)", (t,)); return [r[0] for r in cur.fetchall()]
aff = lambda dt: 'NUMERIC' if dt in ('numeric', 'integer', 'bigint') else 'TEXT'   # the project's Postgres -> SQLite affinity rule (build_ad_seed_patch.sh)
out = {'tables': [], 'rows': [], 'counts': {}}
for t in TABLES:
    cs = cols(t); k = pk(t)
    out['tables'].append({'t': t, 'cols': [c for c, _ in cs], 'pk': k,
                          'ddl': 'CREATE TABLE IF NOT EXISTS %s (%s, PRIMARY KEY (%s))' % (t, ', '.join('%s %s' % (c, aff(d)) for c, d in cs), ', '.join(k))})
    cur.execute('select %s from %s order by %s' % (', '.join(c for c, _ in cs), t, ', '.join(k)))
    rs = cur.fetchall(); out['counts'][t] = len(rs)
    for r in rs: out['rows'].append('INSERT OR IGNORE INTO %s (%s) VALUES (%s)' % (t, ', '.join(c for c, _ in cs), ', '.join(lit(v) for v in r)))
print('// GENERATED by erp/patches/build_ctxhelp_overlay.py from the reference idempiere DB - do not edit by hand. Applied by ad_ctxhelp_overlay.js (boot overlay, outside the team base hash).')
print('(function (g) { var L = ' + json.dumps(out, indent=0, ensure_ascii=False) + ';\n  if (typeof module !== "undefined" && module.exports) module.exports = L; g.AD_CTXHELP_ROWS = L; })(typeof window !== "undefined" ? window : globalThis);')
print('§CTXHELP_OVERLAY_BUILD tables=%d rows=%d counts=%s' % (len(out['tables']), len(out['rows']), json.dumps(out['counts'])), file=sys.stderr)
